1	"use client";
2	
3	import { useState } from "react";
4	import { GAME_VISUAL } from "@/components/marketing/GameLogo";
5	
6	/**
7	 * GameCoverTile — a compact portrait "box-art" cover, the small-scale version of
8	 * the /game-servers hero carousel cover, for use in pickers (e.g. the game deploy
9	 * wizard). Same owner drop-in convention as GameCoverCarousel's cover:
10	 *
11	 *   public/logos/games/covers/<family>.{webp,jpg,png}   ← real key-art, takes over
12	 *   public/logos/games/<family>.png                     ← wordmark fallback
13	 *   per-game gradient                                    ← final fallback
14	 *
15	 * Plain <img> so the onError chain advances client-side. Aspect ~2:3 (poster).
16	 */
17	export function GameCoverTile({ family, name }: { family: string; name: string }) {
18	  const visual = GAME_VISUAL[family] ?? { name, glyph: "🎮", from: "#334155", to: "#64748b" };
19	  const chain = [
20	    `/logos/games/covers/${family}.webp`,
21	    `/logos/games/covers/${family}.jpg`,
22	    `/logos/games/covers/${family}.png`,
23	    `/logos/games/${family}.png`, // wordmark fallback (not full art)
24	  ];
25	  const [idx, setIdx] = useState(0);
26	  const exhausted = idx >= chain.length;
27	  const isWordmark = idx === chain.length - 1;
28	
29	  return (
30	    <div
31	      className="relative aspect-[2/3] w-full overflow-hidden rounded-lg"
32	      style={{ background: `radial-gradient(130% 100% at 50% 0%, ${visual.from}, ${visual.to})` }}
33	    >
34	      {!exhausted && (
35	        // eslint-disable-next-line @next/next/no-img-element
36	        <img
37	          src={chain[idx]}
38	          alt={name}
39	          className={isWordmark ? "absolute inset-0 m-auto h-1/2 w-auto object-contain drop-shadow" : "absolute inset-0 h-full w-full object-cover"}
40	          onError={() => setIdx((i) => i + 1)}
41	        />
42	      )}
43	      {exhausted && (
44	        <span className="absolute inset-0 flex items-center justify-center text-2xl" aria-hidden>
45	          {visual.glyph}
46	        </span>
47	      )}
48	      {/* bottom vignette so a name overlaid by the parent stays legible on any art */}
49	      <div className="pointer-events-none absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-black/70 to-transparent" />
50	    </div>
51	  );
52	}
