1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { useActionState } from "react";
5	import { payAndDeployGame } from "@/lib/actions-gameplans";
6	import { GameLogo } from "@/components/marketing/GameLogo";
7	import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
8	import { GameCoverTile } from "@/components/customer/GameCoverTile";
9	import { TermLadder } from "@/components/customer/TermLadder";
10	import {
11	  PRODUCT_TERMS,
12	  ANNUAL_TERM_MONTHS,
13	  termPriceCents,
14	  vpsTerm,
15	  DEFAULT_ANNUAL_DISCOUNT_PCT,
16	} from "@/lib/billing-terms";
17	import { walletSplit } from "@/lib/wallet-split";
18	import type { ConfigField, FamilySchema } from "@/lib/game-config";
19	import { useCurrency } from "@/components/currency/CurrencyContext";
20	import { convertAndFormat, DEFAULT_CURRENCY } from "@/lib/currency";
21	
22	export type Tier = {
23	  id: string;
24	  gameFamily: string;
25	  name: string;
26	  ramMB: number;
27	  cpuCores: number;
28	  diskGB: number;
29	  slots: number | null;
30	  priceCents: number;
31	  termMonths: number;
32	  featured: boolean;
33	};
34	export type GameMeta = { family: string; name: string; glyph: string };
35	
36	// USD formatter — this wizard's 2-decimal style ("$5.00"). Used verbatim for the
37	// USD display path (byte-for-byte unchanged) and for the "billed in USD" note.
38	const usd = (c: number) => `$${(c / 100).toFixed(2)}`;
39	const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
40	
41	/** Same hostname rule as the server (lib/game-order.ts) + VPS deploy. */
42	const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
43	type Values = Record<string, string | number | boolean>;
44	
45	/** sessionStorage key for the in-progress order — survives the Stripe round-trip. */
46	const DRAFT_KEY = "nxeon.gamedeploy.draft.v1";
47	
48	/** Compact stepper, matching the VPS DeployWizard. */
49	function Stepper({ step, steps }: { step: number; steps: string[] }) {
50	  return (
51	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
52	      {steps.map((s, i) => (
53	        <div key={s} className="flex items-center gap-2">
54	          <span
55	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
56	              i === step
57	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
58	                : i < step
59	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
60	                  : "border-white/10 text-slate-500"
61	            }`}
62	          >
63	            {i < step ? "✓" : i + 1}
64	          </span>
65	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
66	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
67	        </div>
68	      ))}
69	    </div>
70	  );
71	}
72	
73	/** Build the default gameplay values for a family schema. */
74	function defaultValues(schema: FamilySchema | null): Values {
75	  const out: Values = {};
76	  if (!schema) return out;
77	  for (const f of schema.fields) out[f.key] = f.default;
78	  return out;
79	}
80	
81	/**
82	 * A proper multi-step game-server deploy wizard — the game analogue of the VPS
83	 * DeployWizard. Steps: Game → Plan & term → Server settings → Review & checkout.
84	 *
85	 * TRUTH BY CONSTRUCTION: every price is derived from the tier's real DB price
86	 * (`priceCents`) run through `termPriceCents` with the SAME live `annualDiscountPct`
87	 * the server charges and renews at, and the wallet/card split is the same
88	 * `walletSplit` math the action charges. So what the customer sees === what
89	 * `payAndDeployGame` charges. Game bills FULL from month 1 — no first-month-free.
90	 */
91	export function GameDeployWizard({
92	  games,
93	  tiers,
94	  balanceCents,
95	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
96	  schemas,
97	  stripeConfigured,
98	}: {
99	  games: GameMeta[];
100	  tiers: Tier[];
101	  balanceCents: number;
102	  annualDiscountPct?: number;
103	  /** family → per-game customization schema (only families that have one). */
104	  schemas: Record<string, FamilySchema>;
105	  /** Whether card checkout is available (else wallet-only). */
106	  stripeConfigured: boolean;
107	}) {
108	  const [state, action, pending] = useActionState(
109	    payAndDeployGame,
110	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
111	  );
112	  // The embedded Stripe session to mount in a modal on THIS page (no redirect).
113	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
114	
115	  // Only open the payment modal as the result of an EXPLICIT Deploy submit (armed in
116	  // the Deploy button's onClick), so a stale session can never open on its own.
117	  const submittedRef = useRef(false);
118	  useEffect(() => {
119	    if (state?.checkout && submittedRef.current) {
120	      submittedRef.current = false;
121	      // The "game" conversion is fired at FULFILMENT (PurchaseTracker, with the real
122	      // charged value + transaction_id) — NOT here at checkout-start, which would
123	      // count customers who abandon at the payment step.
124	      setCheckoutSession(state.checkout);
125	    }
126	  }, [state]);
127	
128	  const steps = ["Game", "Plan", "Settings", "Review"];
129	  const [step, setStep] = useState(0);
130	
131	  // DISPLAY-ONLY price formatter. USD renders byte-for-byte as before; any other
132	  // selected display currency converts the USD-cents amount for on-screen reference
133	  // only. Everything posted to payAndDeployGame stays USD cents (hidden fields carry
134	  // selections, not money).
135	  const { currency, rate } = useCurrency();
136	  const money = (c: number) =>
137	    currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);
138	
139	  const firstGame = games[0]?.family ?? "";
140	  const [game, setGame] = useState(firstGame);
141	  const [selected, setSelected] = useState<string | null>(null);
142	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
143	  const [serverName, setServerName] = useState("");
144	  const [hostname, setHostname] = useState("");
145	  const [variant, setVariant] = useState("");
146	  const [values, setValues] = useState<Values>({});
147	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
148	  const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);
149	
150	  const gameTiers = useMemo(
151	    () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
152	    [tiers, game],
153	  );
154	  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
155	  const schema = schemas[game] ?? null;
156	
157	  // When the game changes, reset the tier + per-game setup to that game's defaults.
158	  function pickGame(family: string) {
159	    setGame(family);
160	    setSelected(null);
161	    const s = schemas[family] ?? null;
162	    setVariant(s?.defaultVariant ?? "");
163	    setValues(defaultValues(s));
164	  }
165	
166	  // Restore a cancelled-checkout draft (Stripe cancel → /dashboard/games?canceled=1).
167	  useEffect(() => {
168	    let canceled = false;
169	    try {
170	      canceled = new URLSearchParams(window.location.search).get("canceled") === "1";
171	    } catch {
172	      /* no URL access */
173	    }
174	    if (!canceled) return;
175	    setRestoredAfterCancel(true);
176	    let d: any = null;
177	    try {
178	      const raw = sessionStorage.getItem(DRAFT_KEY);
179	      sessionStorage.removeItem(DRAFT_KEY);
180	      if (raw) d = JSON.parse(raw);
181	    } catch {
182	      d = null;
183	    }
184	    if (!d) return;
185	    // Re-check every id against the props actually rendered — a tier can be retired
186	    // while the customer is on Stripe's page.
187	    if (typeof d.game === "string" && games.some((g) => g.family === d.game)) setGame(d.game);
188	    if (typeof d.selected === "string" && tiers.some((t) => t.id === d.selected)) setSelected(d.selected);
189	    if (PRODUCT_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
190	    if (typeof d.serverName === "string") setServerName(d.serverName);
191	    if (typeof d.hostname === "string") setHostname(d.hostname);
192	    if (typeof d.variant === "string") setVariant(d.variant);
193	    if (d.values && typeof d.values === "object") setValues(d.values);
194	    if (typeof d.useWallet === "boolean") setUseWallet(d.useWallet && balanceCents > 0);
195	    if (Number.isInteger(d.step) && d.step >= 0 && d.step < steps.length) setStep(d.step);
196	    // Mount-only: restores a one-shot draft.
197	    // eslint-disable-next-line react-hooks/exhaustive-deps
198	  }, []);
199	
200	  // Persist the draft on every change so it survives the Stripe round-trip.
201	  useEffect(() => {
202	    try {
203	      sessionStorage.setItem(
204	        DRAFT_KEY,
205	        JSON.stringify({ step, game, selected, termMonths, serverName, hostname, variant, values, useWallet }),
206	      );
207	    } catch {
208	      /* storage disabled — the wizard still works */
209	    }
210	  }, [step, game, selected, termMonths, serverName, hostname, variant, values, useWallet]);
211	
212	  // Pricing — identical math to lib/game-order.ts gameOrderQuote, so displayed === charged.
213	  const monthlyCents = chosen ? Math.round(chosen.priceCents / Math.max(1, chosen.termMonths)) : 0;
214	  const chargeCents = chosen ? termPriceCents(monthlyCents, termMonths, annualDiscountPct) : 0;
215	  const dueCents = chargeCents;
216	  const split = walletSplit({ dueCents, balanceCents, useWallet });
217	  const walletApplied = split.walletApplied;
218	  const cardCents = split.cardCents;
219	
220	  const hostnameValid = hostname === "" || (hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname));
221	  // A card leg with no Stripe configured can't settle — the customer must apply
222	  // enough wallet balance to cover the whole charge.
223	  const cardBlocked = cardCents > 0 && !stripeConfigured;
224	
225	  const curLabel = steps[step];
226	  const isLast = step === steps.length - 1;
227	
228	  // Per-step gating with a plain-language blocker (mirrors DeployWizard).
229	  const planBlocker = !chosen ? "Choose a plan to continue." : null;
230	  const settingsBlocker = !hostnameValid
231	    ? "Hostname must be 3–40 characters, using only letters, digits and hyphens (or leave it blank and we'll name it)."
232	    : null;
233	  const deployBlocker = !chosen
234	    ? "Go back to the Plan step and choose a plan."
235	    : !hostnameValid
236	      ? "Fix the hostname on the Settings step."
237	      : cardBlocked
238	        ? "Card checkout isn't set up — apply enough wallet balance to cover the total, or top up your wallet."
239	        : null;
240	  const primaryBlocker = isLast
241	    ? deployBlocker
242	    : curLabel === "Plan"
243	      ? planBlocker
244	      : curLabel === "Settings"
245	        ? settingsBlocker
246	        : null;
247	
248	  const canDeploy = !!chosen && hostnameValid && !cardBlocked;
249	
250	  function setField(key: string, v: string | number | boolean) {
251	    setValues((cur) => ({ ...cur, [key]: v }));
252	  }
253	
254	  return (
255	    <>
256	    <form
257	      action={action}
258	      // Block implicit submit everywhere but the final Review step (a stray Enter in
259	      // the hostname field would otherwise deploy immediately). Deploy only ever
260	      // happens via the explicit button.
261	      onKeyDown={(e) => {
262	        if (e.key === "Enter" && (e.target as HTMLElement).tagName !== "TEXTAREA" && !isLast) {
263	          e.preventDefault();
264	        }
265	      }}
266	      onSubmit={(e) => {
267	        if (!isLast) {
268	          e.preventDefault();
269	          e.stopPropagation();
270	        }
271	      }}
272	    >
273	      {/* Hidden fields — the ONE source the action reads, kept in sync with the UI. */}
274	      <input type="hidden" name="gamePlanId" value={chosen?.id ?? ""} />
275	      <input type="hidden" name="termMonths" value={termMonths} />
276	      <input type="hidden" name="serverName" value={serverName} />
277	      <input type="hidden" name="hostname" value={hostname} />
278	      <input type="hidden" name="variant" value={variant} />
279	      <input type="hidden" name="config" value={JSON.stringify(values)} />
280	      <input type="hidden" name="useWallet" value={useWallet ? "1" : "0"} />
281	
282	      <div className="card">
283	        <Stepper step={step} steps={steps} />
284	        {state?.error && (
285	          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
286	            {state.error}
287	          </div>
288	        )}
289	        {restoredAfterCancel && (
290	          <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">
291	            <span className="font-semibold text-white">Checkout cancelled — you weren&apos;t charged.</span>{" "}
292	            Your game, plan, term and settings are exactly as you left them.
293	          </div>
294	        )}
295	
296	        {/* Step 1 — Game */}
297	        {curLabel === "Game" && (
298	          <div>
299	            <h2 className="mb-1 font-semibold">Choose your game</h2>
300	            <p className="mb-4 text-sm text-slate-400">Pick a game and we&apos;ll size the server for it.</p>
301	            {/* Cover-art picker — the compact version of the /game-servers cover
302	                carousel. Each portrait box-art IS the selectable button. */}
303	            <div className="grid grid-cols-3 gap-3 sm:grid-cols-4 lg:grid-cols-6">
304	              {games.map((g) => {
305	                const active = g.family === game;
306	                const count = tiers.filter((t) => t.gameFamily === g.family).length;
307	                return (
308	                  <button
309	                    type="button"
310	                    key={g.family}
311	                    onClick={() => pickGame(g.family)}
312	                    aria-pressed={active}
313	                    className={`group relative overflow-hidden rounded-xl border text-left transition ${
314	                      active ? "border-brand-400 ring-2 ring-brand-400/50" : "border-white/[0.08] hover:border-white/25"
315	                    }`}
316	                  >
317	                    <GameCoverTile family={g.family} name={g.name} />
318	                    <div className="pointer-events-none absolute inset-x-0 bottom-0 p-2">
319	                      <div className="truncate text-xs font-semibold text-white">{g.name}</div>
320	                      <div className="text-[10px] text-slate-300/80">
321	                        {count} tier{count === 1 ? "" : "s"}
322	                      </div>
323	                    </div>
324	                    {active && (
325	                      <span className="absolute right-1.5 top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-brand-500 text-[11px] text-white shadow">
326	                        ✓
327	                      </span>
328	                    )}
329	                  </button>
330	                );
331	              })}
332	            </div>
333	          </div>
334	        )}
335	
336	        {/* Step 2 — Plan & term */}
337	        {curLabel === "Plan" && (
338	          <div className="space-y-6">
339	            <div>
340	              <div className="mb-3 flex items-center gap-2">
341	                <GameLogo family={game} size={26} />
342	                <h2 className="font-semibold">Choose your {games.find((g) => g.family === game)?.name ?? "game"} plan</h2>
343	              </div>
344	              {gameTiers.length === 0 ? (
345	                <p className="text-sm text-slate-500">No plans are available for this game yet. Check back soon.</p>
346	              ) : (
347	                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
348	                  {gameTiers.map((t) => {
349	                    const active = t.id === selected;
350	                    const tMonthly = Math.round(t.priceCents / Math.max(1, t.termMonths));
351	                    const tPerMo = Math.round(termPriceCents(tMonthly, termMonths, annualDiscountPct) / termMonths);
352	                    return (
353	                      <button
354	                        type="button"
355	                        key={t.id}
356	                        onClick={() => setSelected(t.id)}
357	                        className={`card card-hover text-left transition ${
358	                          active ? "!border-brand-400 ring-1 ring-brand-400/40" : ""
359	                        }`}
360	                      >
361	                        <div className="flex items-center justify-between gap-2">
362	                          <span className="font-semibold text-white">{t.name}</span>
363	                          {t.featured && (
364	                            <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2 py-0.5 text-[11px] text-brand-300">
365	                              Popular
366	                            </span>
367	                          )}
368	                        </div>
369	                        <p className="mt-2 text-2xl font-bold tracking-tight text-white">
370	                          {money(tPerMo)}
371	                          <span className="text-sm font-normal text-slate-400">/mo</span>
372	                        </p>
373	                        <ul className="mt-3 space-y-1 text-sm text-slate-400">
374	                          <li>
375	                            {gb(t.ramMB)} RAM · {t.cpuCores} vCPU
376	                          </li>
377	                          <li>{t.diskGB} GB NVMe disk</li>
378	                          {t.slots != null && <li>Up to {t.slots} player slots</li>}
379	                        </ul>
380	                      </button>
381	                    );
382	                  })}
383	                </div>
384	              )}
385	            </div>
386	
387	            {chosen && (
388	              <div>
389	                <p className="label mb-2">Billing term</p>
390	                <TermLadder
391	                  monthlyCents={monthlyCents}
392	                  annualDiscountPct={annualDiscountPct}
393	                  value={termMonths}
394	                  onChange={setTermMonths}
395	                />
396	                <p className="mt-2 text-xs text-slate-500">
397	                  Billed in full from day one — the price you sign up at is the price you renew at.
398	                </p>
399	              </div>
400	            )}
401	          </div>
402	        )}
403	
404	        {/* Step 3 — Server settings */}
405	        {curLabel === "Settings" && (
406	          <div className="space-y-5">
407	            <div>
408	              <h2 className="font-semibold">Server settings</h2>
409	              <p className="mt-1 text-sm text-slate-400">
410	                Name your server and set it up for {games.find((g) => g.family === game)?.name ?? "your game"}. You can
411	                change everything later from the server&apos;s Game settings tab.
412	              </p>
413	            </div>
414	
415	            <div className="grid gap-4 sm:grid-cols-2">
416	              <label className="block text-sm">
417	                <span className="label mb-1.5 block">
418	                  Server name <span className="text-xs font-normal text-slate-500">optional</span>
419	                </span>
420	                <input
421	                  className="input"
422	                  value={serverName}
423	                  maxLength={60}
424	                  onChange={(e) => setServerName(e.target.value)}
425	                  placeholder="My Survival Server"
426	                />
427	                <span className="mt-1 block text-xs text-slate-500">A friendly nickname shown in your dashboard.</span>
428	              </label>
429	              <label className="block text-sm">
430	                <span className="label mb-1.5 block">
431	                  Hostname <span className="text-xs font-normal text-slate-500">optional</span>
432	                </span>
433	                <input
434	                  className="input"
435	                  value={hostname}
436	                  onChange={(e) => setHostname(e.target.value.toLowerCase())}
437	                  placeholder="auto-generated"
438	                  aria-invalid={!hostnameValid}
439	                />
440	                <span className={`mt-1 block text-xs ${!hostnameValid ? "text-red-300" : "text-slate-500"}`}>
441	                  {!hostnameValid
442	                    ? "3–40 characters, letters, digits and hyphens only."
443	                    : "The name your server answers to — leave blank and we'll pick one."}
444	                </span>
445	              </label>
446	            </div>
447	
448	            {schema ? (
449	              <>
450	                <div>
451	                  <span className="label mb-1.5 block">Server type</span>
452	                  <select className="input max-w-sm" value={variant} onChange={(e) => setVariant(e.target.value)}>
453	                    {schema.variants.map((v) => (
454	                      <option key={v.id} value={v.id}>
