26	function money(cents: number) {
27	  const v = cents / 100;
28	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
29	}
30	function gb(mb: number) {
31	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
32	}
33	function per(term: number) {
34	  return term > 1 ? `/ ${term} mo` : "/mo";
