const [gameSort, setGameSort] = useState<"featured" | "name" | "price">("featured");

const gameTiers = useMemo(
  () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
  [tiers, game],
);
const chosen = gameTiers.find((t) => t.id === selected) ?? null;
const schema = schemas[game] ?? null;

// Cheapest monthly price per family — powers the "from $X/mo" badge + price sort.
const fromMonthlyByFamily = useMemo(() => {
  const m: Record<string, number> = {};
  for (const t of tiers) {
    const mo = Math.round(t.priceCents / Math.max(1, t.termMonths));
    if (m[t.gameFamily] === undefined || mo < m[t.gameFamily]) m[t.gameFamily] = mo;
  }
  return m;
}, [tiers]);
const featuredFamilies = useMemo(
  () => new Set(tiers.filter((t) => t.featured).map((t) => t.gameFamily)),
  [tiers],
);
const tierCountByFamily = useMemo(() => {
  const m: Record<string, number> = {};
  for (const t of tiers) m[t.gameFamily] = (m[t.gameFamily] ?? 0) + 1;
  return m;
}, [tiers]);
// Only surface category pills for genres that actually have games available.
const gameCategories = useMemo(() => {
  const set = new Set<string>();
  for (const g of games) set.add(GAME_GENRE[g.family] ?? "Other");
  return ["All", ...[...set].sort()];
}, [games]);
const visibleGames = useMemo(() => {
  const q = gameQuery.trim().toLowerCase();
  const list = games.filter((g) => {
    if (gameCategory !== "All" && (GAME_GENRE[g.family] ?? "Other") !== gameCategory) return false;
    if (q && !g.name.toLowerCase().includes(q) && !g.family.includes(q)) return false;
    return true;
  });
  const sorted = [...list];
  if (gameSort === "name") sorted.sort((a, b) => a.name.localeCompare(b.name));
  else if (gameSort === "price")
    sorted.sort(
      (a, b) => (fromMonthlyByFamily[a.family] ?? Infinity) - (fromMonthlyByFamily[b.family] ?? Infinity),
    );
  else
    sorted.sort(
      (a, b) => (featuredFamilies.has(b.family) ? 1 : 0) - (featuredFamilies.has(a.family) ? 1 : 0),
    );
  return sorted;
}, [games, gameQuery, gameCategory, gameSort, fromMonthlyByFamily, featuredFamilies]);

