input.new_string:
{/* Step 1 — Game */}
{curLabel === "Game" && (
  <div>
    <div className="mb-5">
      <h2 className="text-lg font-semibold text-white">Choose your game</h2>
      <p className="mt-1 text-sm text-slate-400">
        Pick a game and we&apos;ll size the server for it.
      </p>
    </div>

    {/* Toolbar — search + sort. A restrained glass bar over the navy field. */}
    <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center">
      <div className="relative flex-1">
        <SearchIcon className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" />
        <input
          type="text"
          value={gameQuery}
          onChange={(e) => setGameQuery(e.target.value)}
          placeholder="Search games…"
          aria-label="Search games"
          className="w-full rounded-xl border border-white/[0.08] bg-navy-950/60 py-2.5 pl-9 pr-9 text-sm text-white placeholder:text-slate-500 outline-none transition focus:border-brand-400/60 focus:ring-2 focus:ring-brand-400/20"
        />
        {gameQuery && (
          <button
            type="button"
            onClick={() => setGameQuery("")}
            aria-label="Clear search"
            className="absolute right-2.5 top-1/2 flex h-5 w-5 -translate-y-1/2 items-center justify-center rounded-full text-slate-500 transition hover:bg-white/10 hover:text-white"
          >
            ✕
          </button>
        )}
      </div>
      <label className="flex items-center gap-2 text-xs text-slate-500">
        <span className="hidden sm:inline">Sort</span>
        <select
          value={gameSort}
          onChange={(e) => setGameSort(e.target.value as "featured" | "name" | "price")}
          aria-label="Sort games"
          className="rounded-xl border border-white/[0.08] bg-navy-950/60 px-3 py-2.5 text-sm text-slate-200 outline-none transition focus:border-brand-400/60 focus:ring-2 focus:ring-brand-400/20"
        >
          <option value="featured">Popular first</option>
          <option value="name">Name (A–Z)</option>
          <option value="price">Price (low to high)</option>
        </select>
      </label>
    </div>

    {/* Category pills — only genres that actually have games are shown. */}
    {gameCategories.length > 2 && (
      <div className="mb-5 flex flex-wrap gap-2">
        {gameCategories.map((c) => {
          const on = gameCategory === c;
          return (
            <button
              type="button"
              key={c}
              onClick={() => setGameCategory(c)}
              aria-pressed={on}
              className={`rounded-full border px-3.5 py-1 text-xs font-medium transition ${
                on
                  ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                  : "border-white/[0.08] bg-white/[0.02] text-slate-400 hover:border-white/25 hover:text-slate-200"
              }`}
            >
              {c}
            </button>
          );
        })}
      </div>
    )}

    {/* Cover-art picker — spacious portrait grid. Each box-art IS the button;
        real key-art loads via GameCoverTile's drop-in chain, gracefully
        falling back to the wordmark-on-gradient poster. */}
    {visibleGames.length === 0 ? (
      <div className="rounded-2xl border border-white/[0.06] bg-white/[0.02] px-6 py-14 text-center">
        <p className="text-sm text-slate-400">
          No games match{gameQuery ? <> “{gameQuery}”</> : " that filter"}.
        </p>
        <button
          type="button"
          onClick={() => {
            setGameQuery("");
            setGameCategory("All");
          }}
          className="mt-3 text-xs font-medium text-brand-300 transition hover:text-brand-200"
        >
          Clear filters
        </button>
      </div>
    ) : (
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">
        {visibleGames.map((g) => {
          const active = g.family === game;
          const count = tierCountByFamily[g.family] ?? 0;
          const from = fromMonthlyByFamily[g.family];
          const featured = featuredFamilies.has(g.family);
          return (
            <button
              type="button"
              key={g.family}
              onClick={() => pickGame(g.family)}
              aria-pressed={active}
              className={`group relative overflow-hidden rounded-2xl border text-left transition duration-200 ${
                active
                  ? "border-brand-400 ring-2 ring-brand-400/40 shadow-[0_0_45px_-12px_rgba(111,71,245,0.65)]"
                  : "border-white/[0.08] hover:-translate-y-0.5 hover:border-white/25 hover:shadow-[0_16px_36px_-20px_rgba(0,0,0,0.85)]"
              }`}
            >
              <GameCoverTile family={g.family} name={g.name} />
              {featured && (
                <span className="absolute left-2 top-2 rounded-full border border-white/20 bg-black/50 px-2 py-0.5 text-[10px] font-semibold text-white backdrop-blur">
                  Popular
                </span>
              )}
              {active && (
                <span className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-brand-500 text-xs text-white shadow-lg ring-2 ring-navy-950/70">
                  ✓
                </span>
              )}
              <div className="pointer-events-none absolute inset-x-0 bottom-0 p-3">
                <div className="truncate text-sm font-semibold text-white drop-shadow">{g.name}</div>
                <div className="mt-0.5 flex items-center justify-between gap-2 text-[11px]">
                  <span className="text-slate-300/80">
                    {count} tier{count === 1 ? "" : "s"}
                  </span>
                  {from != null && (
                    <span className="font-semibold text-brand-200">from {money(from)}/mo</span>
                  )}
                </div>
              </div>
            </button>
          );
        })}
      </div>
    )}
  </div>
)}
